data=open('/workspace/output','rb').read().strip()
def rot(c,r): return ((c<<r)|(c>>(8-r)))&255
def rev(c): return int(f'{c:08b}'[::-1],2)
def gray_inv(c):
    r=c
    s=c>>1
    while s: r^=s; s>>=1
    return r
ops={
 'id':lambda c:c,'not':lambda c:c^255,'gray':lambda c:c^(c>>1),'grayinv':gray_inv,'rev':rev,
 'neg':lambda c:(-c)&255,'sub1':lambda c:(c-1)&255,'add1':lambda c:(c+1)&255,
}
for r in range(1,8): ops[f'rotl{r}']=(lambda r: lambda c: rot(c,r))(r); ops[f'rotr{r}']=(lambda r: lambda c: rot(c,8-r))(r)
for n,f in ops.items():
    s=bytes(f(c) for c in data)
    for k in range(256):
        t=bytes(c^k for c in s)
        if b'flag' in t or b'FLAG' in t or b'{' in t: print(n,k,t)
# neighbour xor across stream
for name,s in [('dx',bytes(data[i]^data[i-1] for i in range(1,len(data)))),('dx2',bytes(data[i]^data[i+1] for i in range(len(data)-1)))]:
    print(name,s)
print('ascii', [c for c in data])

